/* Apply 'lining-nums' for consistent, modern headings/prices */
h1, .product-price {
  font-variant-numeric: lining-nums;
  /* Ensures all numbers occupy a consistent height, aligning nicely */
}

/* Use 'tabular-nums' for data tables or financial displays */
.data-table td {
  font-variant-numeric: tabular-nums;
  /* Guarantees numbers have uniform width, preventing "jiggle" in columns */
}

/* Or 'oldstyle-nums' for a classic, flowing look in body text */
p.main-content {
  font-variant-numeric: oldstyle-nums;
  /* Numbers align with x-height, blending better with lowercase letters */
}
